  const center = central ? [0, 0, 0] : minima.map((value, axis) => (value + maxima[axis]) / 2);
  const scale = Math.max(trajectory.viewer.body_radius || 0,
    ...spatial.map((point) => Math.hypot(...point.map((value, axis) => value - center[axis]))), 1);
