  } else {
    const z = (0 - center[2]) / scale;
    const planeCenter = [0, 0, z];
    surface = plane(planeCenter, 1.35, z);
    normals = new Float32Array(18);
    for (let i = 2; i < normals.length; i += 3) normals[i] = 1;
