    try {
        if (!w->origin.data) w->origin.allocate(w->p.columns,w->memory);
        if (!w->translated.data) w->translated.allocate(static_cast<size_t>(w->p.nonzeros)
            +w->a.nonzeros+w->g.nonzeros+w->p.columns+w->a.rows+w->g.rows,w->memory);
