                // exactly the dense matrix used by the independent oracle.
                if ((r + c) % 13 == 0) { indices.push_back(r); values.push_back(a.at(r, c) / 2); }
                indices.push_back(r); values.push_back(a.at(r, c) * ((r + c) % 13 == 0 ? 0.5 : 1.0));
