int main() {
    topology_case();
    run_case(1, 0, 0, {});
    run_case(7, 0, 3, {4, 8});
    run_case(17, 9, 2, {3, 5});
    run_case(513, 201, 7, {4, 32, 257});
    std::puts("GPU QOCO audit: independent dense reference, updates, mapping, stream, nonfinite rejection and 24 translated-coordinate graph replays PASS");
}
